INSERT INTO products (slug, sku, name_en, name_zh, brand, truck_model, category, description_en, description_zh, specs, status) SELECT 'huitian-weld-seam-adhesive', 'DD-ADH-101', 'Sheet Metal Weld Seam Adhesive', '钣金焊缝胶', '回天', NULL, 'adhesive', 'One-component PU weld seam sealant with high thixotropy — non-sagging on vertical and overhead surfaces, low odor, easy to apply by hand. Strong adhesion to a wide range of materials, compatible with anti-corrosion paint, resistant to thermal cycling and dynamic loads. For automotive weld seams, body equipment and box sealing, also for furniture machinery, chemical, construction and engineering machinery. Fillable, waterproof and dustproof. 310 ml/cartridge, 24/box.', '回天聚氨酯系列钣金焊缝胶：单组分、高触变、立面及倒立施工不流淌、低气味，便于手工施工。对各种材质有广泛粘附力，可配套防腐蚀护漆，适应冷热变化与动载荷变动。适用于汽车焊缝、车体设备、箱体密封，以及家具机械、化工、建筑、工程机械等材料间的粘接与密封，可填充、防水、防尘。', '{"类型": "单组分聚氨酯焊缝密封胶", "特点": "高触变、不流淌、低气味", "适用": "焊缝/箱体密封", "包装规格": "310ml/支 × 24支/箱"}'::jsonb, 'published' WHERE NOT EXISTS (SELECT 1 FROM products WHERE slug = 'huitian-weld-seam-adhesive');
INSERT INTO products (slug, sku, name_en, name_zh, brand, truck_model, category, description_en, description_zh, specs, status) SELECT 'suerpu-918-windshield-adhesive', 'DD-ADH-102', 'Suerpu 918 Windshield Adhesive', '苏尔普918风挡玻璃胶', '苏尔普', NULL, 'adhesive', 'High-strength one-component PU windshield adhesive: strong support, non-collapsing glue layer; weather, vibration and water resistant, resistant to chemical media, fast curing. For bonding windshields to cab panels; also for high-strength glass in railway coaches, containers and ship cabins. 310 ml/cartridge or 400 ml/sausage.', '高强度型风挡玻璃胶：强度高、支撑力强、胶层不易塌陷；耐候、耐震动、耐水、耐化学介质腐蚀，固化速度快。主要用于汽车挡风玻璃与钣金体的粘接，亦可用于铁路客车、集装箱、船舱等高强度玻璃粘接。', '{"类型": "单组分湿气固化聚氨酯", "特点": "胶层不易塌陷、支撑力强", "适用": "风挡玻璃与钣金粘接", "包装规格": "310ml/支 × 24支/箱；400ml/包 × 24包/箱"}'::jsonb, 'published' WHERE NOT EXISTS (SELECT 1 FROM products WHERE slug = 'suerpu-918-windshield-adhesive');
INSERT INTO products (slug, sku, name_en, name_zh, brand, truck_model, category, description_en, description_zh, specs, status) SELECT 'suerpu-919-multipurpose-sealant', 'DD-ADH-103', 'Suerpu 919 Multi-purpose PU Sealant', '苏尔普919多用途聚氨酯密封胶', '苏尔普', NULL, 'adhesive', 'Multi-purpose one-component PU sealant: easy to apply with good leveling and durable sealing; sandable and trimmable after cure; weather and heat resistant; non-sagging on vertical surfaces. For seam sealing of automobiles, buses, trucks and cars; also for roof reinforcement, body repair and gap sealing. 310 ml/cartridge, 24/box.', '多用途聚氨酯密封胶：易施工、流平性好，耐久密封性优良；固化后可打磨、可修饰；耐候、耐高温性较好；高触变、立面涂胶不流淌。适用于汽车、客车、货车、轿车焊缝的密封，亦可用于车辆车顶加强、车体维修及箱体等间隙密封。', '{"类型": "单组分聚氨酯密封胶", "特点": "流平性好、固化后可打磨", "适用": "焊缝/间隙密封", "包装规格": "310ml/支 × 24支/箱"}'::jsonb, 'published' WHERE NOT EXISTS (SELECT 1 FROM products WHERE slug = 'suerpu-919-multipurpose-sealant');
INSERT INTO products (slug, sku, name_en, name_zh, brand, truck_model, category, description_en, description_zh, specs, status) SELECT 'suerpu-916-windshield-adhesive', 'DD-ADH-104', 'Suerpu 916 Windshield Adhesive', '苏尔普916风挡玻璃胶', '苏尔普', NULL, 'adhesive', 'Economy one-component PU glass adhesive: solvent-free, non-sagging, moisture-curing and easy to apply; high impact shear strength and good support, no sagging and no glass collapse. For side windows (not for windshield applications per supplier data) and direct bonding to panel surfaces; also for railway coaches, containers and ship cabins. 310 ml/cartridge or 350 ml/sausage.', '经济型聚氨酯玻璃胶：单组分、不含溶剂、不流淌，湿气固化、操作方便；抗冲击剪切强度高、支撑性能好，涂敷不下垂、玻璃不塌陷。适用于侧窗玻璃及钣材表面直接粘接（原资料注明：不含风挡玻璃工况），亦可用于铁路客车、集装箱、船舱等场合。', '{"类型": "单组分湿气固化聚氨酯（经济型）", "特点": "不含溶剂、不流淌", "适用": "侧窗玻璃/钣面粘接", "包装规格": "310ml/支 × 24支/箱；350ml/包 × 24包/箱"}'::jsonb, 'published' WHERE NOT EXISTS (SELECT 1 FROM products WHERE slug = 'suerpu-916-windshield-adhesive');
INSERT INTO products (slug, sku, name_en, name_zh, brand, truck_model, category, description_en, description_zh, specs, status) SELECT 'lg-31-polymer-liquid-sealant', 'DD-ADH-105', 'LG-31 Polymer Liquid Sealant', 'LG-31 高分子液体密封胶', '中配', NULL, 'adhesive', 'Polymer liquid sealant with high-temperature and oil resistance and vibration damping; for sealing mating surfaces of automobiles, motorcycles, machinery and instruments, re-openable after service. Excellent anti-aging and abrasion resistance, resistant to oil, acid and alkali media, non-corrosive to metal. Clean off oil, water, rust and dust before applying evenly at room temperature. 90 g/tube, 100/box.', 'LG-31 高分子液体密封胶：耐高温、耐油、抗振动，广泛用于汽车、摩托车、机械、仪器设备各种结合面的密封，可拆卸使用。具有优越的耐老化、耐磨性与耐油、耐酸、耐碱介质性能，不腐蚀金属表面。使用：先清除被密封表面油、水、铁锈、灰尘，常温下按顺序均匀连续涂敷。', '{"类型": "高分子液体密封胶", "特点": "耐高温、耐油、抗振动", "适用": "结合面密封（可拆卸）", "包装规格": "90g/盒 × 100盒/箱"}'::jsonb, 'published' WHERE NOT EXISTS (SELECT 1 FROM products WHERE slug = 'lg-31-polymer-liquid-sealant');
INSERT INTO products (slug, sku, name_en, name_zh, brand, truck_model, category, description_en, description_zh, specs, status) SELECT 'casting-repair-adhesive', 'DD-ADH-106', 'Casting Repair Adhesive', '铸工胶', '中配', NULL, 'adhesive', 'Two-part epoxy casting repair adhesive (A:B = 1:1): good toughness, oil and water resistance, acid/alkali and corrosion resistance, fast curing with strong repair capability. For repairing porosity, sand holes, pits, cracks and fractures on castings, machinery and equipment; also usable as a general adhesive. Keep the surface dry and clean, mix A:B at 1:1, apply to the defect, then grind and finish after 24 h cure. 100 g/tube, 100/box.', '铸件缺陷修补胶：韧性好、耐油性强、耐水性好、耐酸碱、耐腐蚀，固化快、修补能力强。适用于设备、机械、铸件的气孔、砂眼、麻坑、裂纹、断口等铸造缺陷的修补，也可作一般胶粘剂使用。施工：被粘表面干燥无杂质；A、B 组分按 1:1 比例搅匀，涂于铸件修补处；24 小时固化后打磨修整即可。', '{"类型": "双组分环氧修补胶", "配比": "A:B = 1:1", "特点": "韧性好、耐油、耐水、耐酸碱", "适用": "铸件气孔/砂眼/裂纹修补", "包装规格": "100g/盒 × 100盒/箱"}'::jsonb, 'published' WHERE NOT EXISTS (SELECT 1 FROM products WHERE slug = 'casting-repair-adhesive');
INSERT INTO products (slug, sku, name_en, name_zh, brand, truck_model, category, description_en, description_zh, specs, status) SELECT 'cylinder-block-repair-agent', 'DD-ADH-107', 'Cylinder Block Repair Agent', '缸体修复剂', '中配', NULL, 'adhesive', 'High-strength two-part repair agent (mix ratio 3:1) with excellent temperature resistance. For repairing external leaks of engine cylinder blocks, sealing tank and water-tank joints, and pipeline repair. Prepare the defect into a V-groove after grinding, mix at 3:1 and apply evenly, tap lightly to drive out air bubbles; cures in 24 h at room temperature (60–70% strength), or about 2 h at 80 °C for maximum strength. 150 g/tube, 18/box.', '发动机缸体修复剂：粘接强度高、固化后强度高、耐温性能优。主要用于汽车缸体外部渗漏的修复，以及各种设备箱体、水箱接缝处的堵漏与管路修补，操作简便、维修方便。施工：先检修缸体并清除缺陷，裂纹处打磨并加工成 V 形沟槽；按 3:1 配比调胶均匀后涂敷，轻敲铸件驱赶气泡、挤匀胶层；常温 24 小时固化（达强度 60–70%），加热至 80℃ 约 2 小时可达最大强度。', '{"类型": "双组分环氧修复剂", "配比": "3:1", "特点": "粘接强度高、固化后强度高、耐温性能优", "适用": "缸体渗漏/箱体水箱堵漏", "包装规格": "150g/盒 × 18盒/箱"}'::jsonb, 'published' WHERE NOT EXISTS (SELECT 1 FROM products WHERE slug = 'cylinder-block-repair-agent');
